parameters.jsCode:
const src = $('Sources').item.json;
const status = $json.statusCode ?? null;
const raw = $json.data ?? '';
const html = typeof raw === 'string' ? raw : JSON.stringify(raw);

const text = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<head[\s\S]*?<\/head>/gi, ' ')
  .replace(/<\/(h[1-6]|li|p|div|tr|article|section|header|main)>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/&middot;/g, '·')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n\s*\n+/g, '\n')
  .trim();

const ok = status >= 200 && status < 300 && text.length >= 30;

return { json: {
  run_id: 'R-' + $execution.id,
  test_case: src.test_case,
  competitor_id: src.competitor_id,
  source_type: src.source_type,
  url: src.url,
  retrieved_at: new Date().toISOString(),
  http_status: status,
  fetch_status: ok ? 'ok' : 'fetch_failed',
  fetch_error: ok ? null : (status === null ? 'no HTTP response' : status >= 400 ? 'HTTP ' + status : text.length === 0 ? 'empty successful response' : 'unreadable content'),
  clean_text: text.slice(0, 12000)
}};

