parameters.jsCode:
const ctx = $('Fetch ok?').all(0)[$itemIndex].json;
const features = $('Features').first().json.features;
const ids = features.map(f => f.id);
const raw = $json.output?.entries || [];

const slug = s => String(s || 'unknown').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
const base = { run_id: ctx.run_id, test_case: ctx.test_case, competitor_id: ctx.competitor_id,
  source_url: ctx.url, source_type: ctx.source_type, retrieved_at: ctx.retrieved_at };

if (raw.length === 0) {
  return { json: { entries: [{
    ...base, feature_id: null, matched_via: 'none', raw_feature_name: 'No entries found',
    title: 'No entries found', description: '', entry_date: null, status: 'uncertain', confidence: 0,
    reason: 'Page loaded (HTTP ' + ctx.http_status + ') but no release entries could be extracted. Not treated as removal.',
    idempotency_key: `${ctx.competitor_id}|no_entries|uncertain|nodate`
  }]}};
}

const entries = raw.map(e => {
  const overrides = [];
  let status = ['shipped', 'announced', 'uncertain'].includes(e.status) ? e.status : 'uncertain';
  const fid = ids.includes(e.matched_feature_id) ? e.matched_feature_id : null;
  const date = /^\d{4}-\d{2}-\d{2}$/.test(e.date || '') ? e.date : null;
  const conf = Math.max(0, Math.min(1, Number(e.confidence) || 0));

  // Rename detection: does the entry mention a known alias of the matched feature?
  let via = fid ? (e.matched_via === 'alias' ? 'alias' : 'name') : 'none';
  let renamedFrom = null;
  if (fid) {
    const feat = features.find(f => f.id === fid);
    const hay = ((e.title || '') + ' ' + (e.description || '')).toLowerCase();
    renamedFrom = (feat.aliases || []).find(a => hay.includes(a.toLowerCase())) || null;
    if (renamedFrom) via = 'alias';
  }

  if (ctx.source_type === 'blog' && status === 'shipped') { status = 'announced'; overrides.push('blog source cannot be shipped'); }
  if (!date && status !== 'uncertain') { status = 'uncertain'; overrides.push('missing date'); }
  if (conf < 0.6 && status !== 'uncertain') { status = 'uncertain'; overrides.push('low confidence'); }

  let reason = (e.reason || 'No reason returned by model').trim();
  if (renamedFrom) reason += ` [rename detected: old name "${renamedFrom}" mapped to existing feature ${fid}]`;
  if (overrides.length) reason += ` [rule override: ${overrides.join('; ')}]`;
  if (!fid) reason += ' [not in tracked feature list]';

  return { ...base, feature_id: fid, matched_via: via, raw_feature_name: e.title || 'Unknown',
    title: e.title || 'Unknown', description: e.description || '', entry_date: date, status,
    confidence: conf, reason,
    idempotency_key: `${ctx.competitor_id}|${fid || slug(e.title)}|${status}|${date || 'nodate'}` };
});

return { json: { entries } };

const s = $json;
const urlSlug = String(s.url).replace(/[^a-z0-9]+/gi, '_').slice(-50);
return { json: {
  run_id: s.run_id, test_case: s.test_case, competitor_id: s.competitor_id,
  source_url: s.url, source_type: s.source_type, retrieved_at: s.retrieved_at,
  feature_id: null, matched_via: 'none',
  raw_feature_name: 'Source unavailable',
  title: 'Source unavailable: ' + s.url,
  description: s.fetch_error || '',
  entry_date: null,
  status: 'uncertain', confidence: 1,
  reason: `Source page unavailable (${s.fetch_error}). Cannot conclude any feature was removed.`,
  idempotency_key: `${s.competitor_id}|source_unavailable_${urlSlug}|uncertain|${String(s.retrieved_at).slice(0, 10)}`
}};

const features = $input.all().map(i => ({
  id: i.json.id,
  name: i.json.standard_name,
  aliases: i.json.aliases || []
}));
return [{ json: { features } }];

const TC4_404_URL = ''; // Configure only a controlled endpoint verified to return HTTP 404.
const out = [];
for (const item of $input.all()) {
 const c = item.json;
 const add = (configuredUrl, type) => {
  if (!configuredUrl) return;
  const match = String(configuredUrl).match(/\/tc(\d)[^\/]*$/i);
  const testCase = match ? 'TC' + match[1] : null;
  if (testCase === 'TC4' && !TC4_404_URL) return;
  out.push({ json: { test_case: testCase, competitor_id: c.id, source_type: type, url: testCase === 'TC4' ? TC4_404_URL : configuredUrl } });
 };
 add(c.changelog_url, 'changelog');
 add(c.blog_url, 'blog');
}
return out;

const rows = $input.all().map(i => i.json);
const fetches = $('Normalize fetch').all().map(i => i.json);
const httpOf = tc => (fetches.find(f => f.test_case === tc) || {}).http_status ?? null;
const spec = {
 TC1: { scenario: 'New feature in changelog', expected: 'Row with status shipped, a date and a source link', check: r => r.status === 'shipped' && !!r.entry_date && !!r.source_url },
 TC2: { scenario: 'Feature in marketing post only', expected: 'Marked announced, not shipped', check: r => r.status === 'announced' },
 TC3: { scenario: 'Feature renamed', expected: 'Mapped to the existing row (feat_ai_reply), not a new one', check: r => r.feature_id === 'feat_ai_reply' && r.matched_via === 'alias' },
 TC4: { scenario: 'Changelog page removed (404)', expected: 'Observed HTTP 404 and classified uncertain', check: r => r.status === 'uncertain' }
};
return Object.keys(spec).map(tc => {
 const r = rows.find(x => x.test_case === tc);
 const configured = !!fetches.find(f => f.test_case === tc);
 const http = httpOf(tc);
 const runnable = !!r && configured && (tc !== 'TC4' || http === 404);
 const passed = runnable && spec[tc].check(r);
 const execution_status = !runnable ? 'not_run' : passed ? 'passed' : 'failed';
 let actual_result;
 if (!configured) actual_result = 'NOT RUN: source is not configured.';
 else if (tc === 'TC4' && http !== 404) actual_result = 'NOT RUN: expected HTTP 404; observed ' + (http === null ? 'no HTTP response' : 'HTTP ' + http);
 else if (!r) actual_result = 'FAIL: no classified row was produced.';
 else actual_result = 'status=' + r.status + '; feature=' + (r.feature_id || 'none') + '; matched_via=' + r.matched_via + '; date=' + (r.entry_date || 'none') + '; HTTP ' + (http === null ? 'n/a' : http);
 return { json: { id: tc, scenario: spec[tc].scenario, input_url: r?.source_url || '', expected_result: spec[tc].expected, actual_result, evidence: runnable ? r.reason + ' (run ' + r.run_id + ', source: ' + r.source_url + ')' : null, passed, execution_status } };
});

const rows = $('Merge').all().map(i => i.json);
const prev = $('Get approved').all().map(i => i.json).filter(r => r.competitor_id);
const keyOf = r => `${r.competitor_id}|${r.feature_id || r.title || r.raw_feature_name}`;
const prevMap = new Map(prev.map(r => [keyOf(r), r]));
const runId = rows[0]?.run_id || 'unknown';

const classify = r => {
  const p = prevMap.get(keyOf(r));
  if (!p) return { change: 'new', from: null };
  if (p.status === r.status) return { change: 'unchanged', from: p.status };
  if (p.status === 'announced' && r.status === 'shipped') return { change: 'newly_shipped', from: p.status };
  if (r.status === 'uncertain') return { change: 'uncertain', from: p.status };
  return { change: 'changed', from: p.status };
};

const items = rows.map(r => ({ ...r, ...classify(r) }));
const groups = { shipped: [], announced: [], uncertain: [] };
for (const r of items) (groups[r.status] || groups.uncertain).push(r);

const tag = r => r.change === 'new' ? ' [NEW]'
  : r.change === 'newly_shipped' ? ' [NEWLY SHIPPED]'
  : r.change === 'changed' ? ` [CHANGED from ${r.from}]`
  : r.change === 'uncertain' ? ` [NOW UNCERTAIN, was ${r.from}]` : '';
const line = r => `- **${r.title}**${tag(r)} (${r.competitor_id}, ${r.entry_date || 'no date'}) — [source](${r.source_url}) — ${r.reason}`;
const section = (name, list) => `## ${name}\n` + (list.length ? list.map(line).join('\n') : 'None this week.');

const counts = { new: 0, newly_shipped: 0, changed: 0, uncertain: 0, unchanged: 0 };
items.forEach(r => counts[r.change] = (counts[r.change] || 0) + 1);

const markdown = [
  `# Weekly Competitor Digest (run ${runId})`,
  `Generated: ${new Date().toISOString()}`,
  `Compared with ${prev.length} previously approved entries: ${counts.new} new, ${counts.newly_shipped} newly shipped, ${counts.changed} changed, ${counts.uncertain} now uncertain, ${counts.unchanged} unchanged.`,
  '',
  section('Shipped', groups.shipped), '',
  section('Announced (not yet shipped)', groups.announced), '',
  section('Uncertain', groups.uncertain)
].join('\n');

return [{ json: {
  status: 'waiting_approval',
  diff_summary: JSON.stringify({
    run_id: runId, markdown, previous_approved: prev.length,
    counts: { shipped: groups.shipped.length, announced: groups.announced.length, uncertain: groups.uncertain.length },
    diff_counts: counts,
    items: items.map(r => ({ test_case: r.test_case, title: r.title, status: r.status, change: r.change, previous_status: r.from,
      feature_id: r.feature_id, matched_via: r.matched_via, entry_date: r.entry_date, source_url: r.source_url, reason: r.reason }))
  })
}}];

const b = $input.first().json.body || {};
const list = Array.isArray(b.decisions) ? b.decisions : [];
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const valid = list.filter(d => uuid.test(d.id || '') && ['approved', 'rejected'].includes(d.decision));
if (!valid.length) throw new Error('No valid decisions. Send {"decisions":[{"id":"<uuid>","decision":"approved|rejected"}]}');
return valid.map(d => ({ json: { id: d.id, decision: d.decision, approved_by: String(b.approved_by || 'demo-user').slice(0, 60) } }));

parameters.query:
SELECT id, approval_status, approved_by
FROM entries
WHERE id IN ({{ $('Validate decisions').all().map(i => "'" + i.json.id + "'").join(',') }});

parameters.jsCode:
const wanted = $('Validate decisions').all().map(i => i.json);
const got = new Map($('Read back').all().map(i => [i.json.id, i.json]));
return wanted.map(w => {
  const g = got.get(w.id);
  const ok = !!g && g.approval_status === w.decision;
  return { json: { id: w.id, verify_status: ok ? 'match' : 'mismatch' } };
});

const rows = $input.all().map(i => i.json).filter(r => r.id);
return rows.map(r => {
  const problems = [];
  if (!r.approved_by) problems.push('approved_by missing');
  if (!r.approved_at) problems.push('approved_at missing');
  if (!r.source_url || !r.reason) problems.push('evidence missing');
  if (r.approval_status === 'approved' && r.status !== 'uncertain' && !r.entry_date) problems.push('dated evidence missing');
  if (r.proposed_status && r.proposed_status !== r.status) problems.push(`status changed since proposal (${r.proposed_status} -> ${r.status})`);
  return { json: {
    id: r.id,
    verify_status: problems.length ? 'mismatch' : 'match',
    note: problems.length ? problems.join('; ') : (r.proposed_status ? 'matches the proposal' : 'checked without a digest snapshot')
  }};
});;

const source = $json;
const allowedHost = 'darpan01tech.github.io';
let url = String(source.url || '');
let valid = false;
let reason = 'URL rejected: demo allowlist permits HTTPS on ' + allowedHost + ' only.';
try {
 const parsed = new URL(url);
 valid = parsed.protocol === 'https:' && parsed.hostname.toLowerCase() === allowedHost && !parsed.username && !parsed.password && (!parsed.port || parsed.port === '443');
 if (valid) url = parsed.toString();
} catch {}
return { json: { ...source, url, url_valid: valid, fetch_error: valid ? null : reason, run_id: 'R-' + $execution.id, retrieved_at: new Date().toISOString() } };
